package com.cookly.actividades;
import android.os.Bundle;import android.text.InputType;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;
public class ActividadNuevaReceta extends AppCompatActivity{@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(24,32,24,24);l.setBackgroundColor(0xffFFF8F3);TextView h=new TextView(this);h.setText("Crea una receta\n\n📷 Añade una foto al publicarla próximamente");h.setTextSize(24);h.setTypeface(null,1);l.addView(h);EditText n=campo("Nombre de tu receta");EditText i=campo("Ingredientes (ej. 1 taza arroz, 2 cucharaditas sal)");EditText p=campo("Pasos de preparación");p.setMinLines(4);EditText m=campo("Tiempo en minutos");m.setInputType(InputType.TYPE_CLASS_NUMBER);l.addView(n);l.addView(i);l.addView(p);l.addView(m);Button publicar=new Button(this);publicar.setText("Publicar receta");publicar.setOnClickListener(v->{if(n.getText().toString().trim().isEmpty()||i.getText().toString().trim().isEmpty())Toast.makeText(this,"Añade al menos un nombre e ingredientes",Toast.LENGTH_SHORT).show();else{Toast.makeText(this,"¡Receta guardada! Se publicará al sincronizar con el servidor.",Toast.LENGTH_LONG).show();finish();}});l.addView(publicar);setContentView(l);}private EditText campo(String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextSize(16);e.setPadding(10,12,10,12);return e;}}
